import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"What is TRAPI?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),i={name:"guide/index.md"};function s(n,t,d,l,p,c){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="what-is-trapi" tabindex="-1">What is TRAPI? <a class="header-anchor" href="#what-is-trapi" aria-label="Permalink to &quot;What is TRAPI?&quot;">​</a></h1><p><strong>T</strong>ypeScript <strong>R</strong>est <strong>API</strong> is a suite of packages that extracts REST API metadata from TypeScript decorators and turns it into OpenAPI 2.0, 3.0, 3.1, or 3.2 specifications — without locking you into a specific decorator library.</p><p>Most tools in this space ship their own decorator set that you have to adopt. TRAPI takes the opposite approach: you describe how your existing decorators (custom or third-party) map to a shared semantic model, and TRAPI takes it from there.</p><h2 id="at-a-glance" tabindex="-1">At a Glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a Glance&quot;">​</a></h2><ul><li><strong>Decorator-agnostic</strong> — use any decorator library, bring your own mapping or a preset</li><li><strong>Pure AST analysis</strong> — decorators stay as no-op markers; all work happens at build time</li><li><strong>Zero runtime overhead</strong> — the generated spec is static, nothing ships to production</li><li><strong>Composable</strong> — metadata can feed OpenAPI, code generators, validators, or SDK tooling</li><li><strong>Spec-compliant</strong> — tested against the official OpenAPI JSON Schemas</li></ul><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypeScript source  →  @trapi/metadata  →  Metadata  →  @trapi/swagger  →  OpenAPI spec</span></span>
<span class="line"><span>   (decorators)        (AST analysis)     (normalised)    (emitters)       (JSON/YAML)</span></span></code></pre></div><p>The metadata model is a first-class output. Other consumers — route generators, runtime validators, typed API clients — can be built on top of it without knowing anything about OpenAPI.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/guide/metadata-installation.html"><code>@trapi/metadata</code></a></td><td>Extracts metadata from decorated TypeScript source</td></tr><tr><td><a href="/guide/swagger-installation.html"><code>@trapi/swagger</code></a></td><td>Emits OpenAPI 2.0, 3.0, 3.1 &amp; 3.2 specs from metadata</td></tr><tr><td><code>@trapi/preset-decorators-express</code></td><td>Self-contained preset for <a href="https://github.com/serhiisol/node-decorators" target="_blank" rel="noreferrer">@decorators/express</a> (routing + TRAPI markers + JSDoc handlers)</td></tr><tr><td><code>@trapi/preset-typescript-rest</code></td><td>Self-contained preset for <a href="https://github.com/thiagobustamante/typescript-rest" target="_blank" rel="noreferrer">typescript-rest</a> (routing + TRAPI markers + JSDoc handlers)</td></tr></tbody></table><h2 id="where-to-next" tabindex="-1">Where to Next <a class="header-anchor" href="#where-to-next" aria-label="Permalink to &quot;Where to Next&quot;">​</a></h2><ul><li>New to TRAPI? Start with the <a href="/guide/quick-start.html">Quick Start</a>.</li><li>Curious about the design trade-offs? Read the <a href="/guide/philosophy.html">Philosophy</a>.</li><li>Need a mental model of how pieces fit together? See <a href="/guide/concepts.html">Key Concepts</a>.</li><li>Already using a framework? Jump to <a href="/guide/framework-integration.html">Framework Integration</a>.</li></ul>`,12)])])}const u=e(i,[["render",s]]);export{g as __pageData,u as default};
